		c = 0
		s = 0
		for i in cw:
			s += i
			while s > 1 << c:
				c += 1
			sl[c] = s
		sr = [0] * (d + 1)
		c = 0
		s = 0
		for i in cw[-1::-1]:
			s += i
			while s > 1 << c:
				c += 1
			sr[c] = s
		ans = (1 << d) - n + 2
		for a in range(d):
			for b in range(d):
				lr = sl[a] + sr[b]
				c = 1
