def solve(A, B, C, D, E=3 ** 30):
	if not E:
		return abs(A - C) + abs(B - D)
	a = A // E
	b = B // E
	c = C // E
	d = D // E
	if a != c and b != d:
		return abs(A - C) + abs(B - D)
	if a == c and b == d:
		return solve(A, B, C, D, E // 3)
	if b == d and a != c:
		(A, B) = (B, A)
		(a, b) = (b, a)
		(C, D) = (D, C)
		(c, d) = (d, c)
	if a == c and b != d:
		if a % 3 != 1:
			return solve(A, B, C, D, E // 3)
		if abs(b - d) == 1:
			return solve(A, B, C, D, E // 3)
		if B > D:
			(A, B, C, D) = (C, D, A, B)
			(a, b, c, d) = (c, d, a, b)
		x1 = E * a - 1
		y1 = E * (b + 1) - 1
		y2 = E * d
		dist1 = abs(x1 - A) + abs(y1 - B) + abs(y1 - y2) + abs(x1 - C) + abs(y2 - D)
		x1 = E * (a + 1)
		y1 = E * (b + 1) - 1
		y2 = E * d
		dist2 = abs(x1 - A) + abs(y1 - B) + abs(y1 - y2) + abs(x1 - C) + abs(y2 - D)
		return min(dist1, dist2)
