class disjoinSet(object):

	def __init__(self, n):
		self.father = [x for x in range(0, n + 1)]
		self.rank = [0 for x in range(0, n + 1)]

	def setOf(self, x):
		if self.father[x] != x:
			self.father[x] = self.setOf(self.father[x])
		return self.father[x]

	def Merge(self, x, y):
		xR = self.setOf(x)
		yR = self.setOf(y)
		if xR == yR:
			return
		if self.rank[xR] < self.rank[yR]:
			self.father[xR] = yR
			size[yR] += size[xR]
		elif self.rank[xR] > self.rank[yR]:
			self.father[yR] = xR
			size[xR] += size[yR]
		else:
			self.father[yR] = xR
			size[xR] += size[yR]
			self.rank[xR] += 1

