def precompute(pat):
	totalLen = len(pat)
	lps = [0 for _ in range(totalLen)]
	length = 0
	i = 1
	while i < totalLen:
		if pat[i] == pat[length]:
			length += 1
			lps[i] = length
			i += 1
		elif length != 0:
			length = lps[length - 1]
		else:
			lps[i] = 0
			i += 1
	return lps

def KMPSearch(pat, text):
	lps = precompute(pat)
	(patLen, textLen) = (len(pat), len(text))
	(i, j) = (0, 0)
	while textLen - i >= patLen - j:
		if text[i] == pat[j]:
			i += 1
			j += 1
		if j == patLen:
			return True
		elif i < textLen and text[i] != pat[j]:
			if j != 0:
				j = lps[j - 1]
			else:
				i += 1
	return False

