	return ans

def factor(n):
	pws = []
	dv = 2
	lp = 0
	while n % dv == 0:
		lp += 1
		n //= dv
	if lp:
		pws.append(lp)
	dv = 3
	while n > 1 and dv * dv <= n:
		lp = 0
		while n % dv == 0:
			lp += 1
			n //= dv
		if lp:
			pws.append(lp)
		dv += 2
	if n > 1:
		pws.append(1)
	return pws

