			temp = readIntArr()
			temp.pop(0)
			for j in range(len(temp)):
				temp[j] -= 1
			req[i] = temp
		hasCycle = [False]
		visited = [False] * n
		path = [False] * n

		@bootstrap
		def dfs(book):
			for nex in req[book]:
				if hasCycle[0]:
					yield None
				if path[nex]:
					hasCycle[0] = True
					yield None
				if visited[nex] == False:
					visited[nex] = True
					path[nex] = True
					yield dfs(nex)
					path[nex] = False
			yield None
		for i in range(n):
			if not visited[i]:
				path[i] = True
				visited[i] = True
				dfs(i)
				path[i] = False
		if hasCycle[0]:
			allans.append(-1)
			continue
		memo = [-1] * n

		@bootstrap
		def dp(book):
			if memo[book] == -1:
				ans = 1
				for prev in req[book]:
					if prev < book:
						ans = max(ans, (yield dp(prev)))
					else:
						ans = max(ans, 1 + (yield dp(prev)))
				memo[book] = ans
			yield memo[book]
		ans = 0
		for book in range(n):
			ans = max(ans, dp(book))
		allans.append(ans)
	multiLineArrayPrint(allans)
	return
