def mat_mul(X, Y, mod):
	m = len(X)
	return [[sum((X[i][k] * Y[k][j] % mod for k in range(m))) % mod for j in range(m)] for i in range(m)]

def mat_pow(M, k, mod):
	m = len(M)
	res = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
	while k > 0:
		if k & 1:
			res = mat_mul(M, res, mod)
		M = mat_mul(M, M, mod)
		k >>= 1
	return res

