def append(path, x):
	if not path:
		return Path(1, 1, x, None, None)
	l = path.length + 1
	if l >= 2 * path.midlength:
		return Path(l, path.midlength * 2, x, path, None)
	else:
		return Path(l, path.midlength, path.middle, path.left, append(path.right, x))
