def gcp(x, y):
	if not x or not y:
		return 0
	while x.midlength > y.midlength:
		x = x.left
	while y.midlength > x.midlength:
		y = y.left
	if x.middle == y.middle:
		return x.midlength + gcp(x.right, y.right)
	else:
		return gcp(x.left, y.left)

def dist(x, y):
	px = paths[x]
	py = paths[y]
	return px.length + py.length - 2 * gcp(px, py)
